#requires -Version 5.1
$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$module=Import-Module (Join-Path $PSScriptRoot '../src/WindowsServerMigration.psd1') -Force -PassThru
$root=Join-Path $env:TEMP ('wsm-wprepb-'+[Guid]::NewGuid().ToString('N').Substring(0,8));[void][IO.Directory]::CreateDirectory($root)
try {
    & $module {
        param($Root,$BulkHelper)
        . $BulkHelper
        $script:bulkChecks=0
        function Check([bool]$Condition,[string]$Message){if(-not $Condition){throw $Message};$script:bulkChecks++}
        function Reject([scriptblock]$Action,[string]$Message){$failed=$false;try{& $Action|Out-Null}catch{$failed=$true};Check $failed $Message}
        $work=Join-Path $Root 'manager';Initialize-WsmWizardWorkspace $work Manager|Out-Null
        $source=[pscustomobject]@{HostId=[Guid]::NewGuid().ToString('D');Fingerprint=('a'*64);Name='Bulk preparation fixture source'}
        $file=New-WsmItem $source.HostId Storage PathCandidate 'Fixture business files' 'C:\FixtureData\business' ([pscustomobject][ordered]@{OriginalPath='C:\FixtureData\business';ResolvedCandidate='C:\FixtureData\business'})
        $shareSettings=[pscustomobject][ordered]@{Definition=[pscustomobject][ordered]@{Name='FixtureShare';ScopeName='*';Path='C:\FixtureData\share';Description='Fixture share';EncryptData=$false};Access=@([pscustomobject][ordered]@{AccountName='FIXTURE\Readers';AccessControlType='Allow';AccessRight='Read'})}
        $share=New-WsmItem $source.HostId Storage Share 'Fixture SMB share' 'FixtureShare' $shareSettings @() Success SmbShare
        $supplement=[pscustomobject][ordered]@{ServiceType='Win32OwnProcess';ErrorControl='Normal';LoadOrderGroup='';DelayedAutoStart=$false;FailureActions=[pscustomobject][ordered]@{ResetPeriodSeconds=0;RebootMessage='';Command='';Actions=@()};FailureActionsOnNonCrashFailures=$false;ServiceSidType='None';RequiredPrivileges=@();Environment=@();Triggers=@()}
        $serviceSettings=[pscustomobject][ordered]@{Name='FixtureSvc';DisplayName='Fixture service';Description='Fixture service description';PathName='C:\Fixture\service.exe';StartMode='Disabled';StartName='LocalSystem';ServiceType='Win32OwnProcess';Supplement=$supplement}
        $service=New-WsmItem $source.HostId Services Service 'Fixture service' 'FixtureSvc' $serviceSettings @() Success Service
        $passwordServiceSettings=[pscustomobject][ordered]@{Name='FixturePasswordSvc';DisplayName='Fixture password service';Description='Fixture password service description';PathName='C:\Fixture\password-service.exe';StartMode='Disabled';StartName='FIXTURE\svc-account';ServiceType='Win32OwnProcess';Supplement=$supplement}
        $passwordService=New-WsmItem $source.HostId Services Service 'Fixture user-password service' 'FixturePasswordSvc' $passwordServiceSettings @() Success Service
        $groupSettings=[pscustomobject][ordered]@{Name='Fixture Operators';SID='S-1-5-21-111111111-222222222-333333333-2001';Members=@([pscustomobject][ordered]@{Name='fixture-reader';Domain='FIXTURE';SID='S-1-5-21-111111111-222222222-333333333-1002'})}
        $group=New-WsmItem $source.HostId Identity LocalGroup $groupSettings.Name $groupSettings.SID $groupSettings @() Success LocalGroup
        $userSettings=[pscustomobject][ordered]@{Name='fixture-user';SID='S-1-5-21-111111111-222222222-333333333-1001';Disabled=$true;FullName='Fixture user';Description='Fixture account'}
        $user=New-WsmItem $source.HostId Identity LocalUser 'Fixture local user' $userSettings.SID $userSettings @() Success LocalUser
        $xml='<Task xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task"><Principals><Principal><UserId>SYSTEM</UserId><LogonType>ServiceAccount</LogonType></Principal></Principals><Triggers/><Settings><Enabled>false</Enabled><MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy></Settings><Actions><Exec><Command>C:\Fixture\job.exe</Command><WorkingDirectory>C:\Fixture</WorkingDirectory></Exec></Actions></Task>'
        $task=New-WsmItem $source.HostId Tasks ScheduledTask 'Fixture task' '\Fixture\BulkJob' ([pscustomobject][ordered]@{TaskName='BulkJob';TaskPath='\Fixture\';Xml=$xml})
        $inventory=New-WsmInventory $source 1 @($file,$share,$service,$passwordService,$group,$user,$task);$inventoryPath=Join-Path $Root 'inventory.json';Write-WsmJson $inventoryPath $inventory
        $catalog=Import-WsmInventory $work $inventoryPath (Get-FileHash -LiteralPath $inventoryPath -Algorithm SHA256).Hash 'bulk review fixture'
        $catalog=Enable-WsmAssistiveMode $work $catalog.PairId $catalog.DecisionRevision
        foreach($itemId in @($file.ItemId,$share.ItemId,$service.ItemId,$passwordService.ItemId,$group.ItemId,$user.ItemId,$task.ItemId)){$current=Get-WsmCatalog $work $catalog.PairId;Set-WsmWizardChoice -Workspace $work -PairId $catalog.PairId -Role Manager -ItemId $itemId -Selected $true -ExpectedDecisionRevision $current.DecisionRevision -ExpectedSelectionRevision $current.Assistive.Selections.Revision|Out-Null}
        $catalog=Get-WsmCatalog $work $catalog.PairId
        $preview=Get-WsmWizardBulkPreparationPreview -Workspace $work -PairId $catalog.PairId
        $bulkDefaults=Get-WsmWizardActionDefaults -Workspace $work -PairId $catalog.PairId -Role Manager -Action BulkPreparationSave
        Check ($bulkDefaults.args.PreviewId -ceq $preview.PreviewId -and $bulkDefaults.args.PreviewHash -ceq $preview.PreviewHash -and @($bulkDefaults.missingFields|Where-Object name -CEQ Owner).Count -eq 1 -and -not $bulkDefaults.args.PSObject.Properties['ReviewedSourceDefaults']) 'Bulk defaults lost the sole protected current preview or fabricated owner/source-default consent.'
        Check ($preview.Kind -ceq 'WizardBulkPreparationPreview' -and $preview.PreviewHash -match '^[a-f0-9]{64}' -and -not $preview.AuthoritativeApproval) 'The bulk preview omitted its protected identity/hash or implied approval.'
        Check (@($preview.CandidateItemIds|Where-Object {$_ -in @($service.ItemId,$group.ItemId)}).Count -eq 2) 'The bulk preview did not include both safe Service and LocalGroup candidates.'
        Check (@($preview.DeferredFields|Where-Object {$_.ItemId -ceq $file.ItemId -and $_.Field -ceq 'ConfigFiles'}).Count -gt 0) 'ExactFiles with no explicit whitelist was not deferred.'
        Check (@($preview.DeferredFields|Where-Object {$_.ItemId -ceq $share.ItemId}).Count -gt 0) 'The SMB adapter with a missing drain decision was not deferred.'
        Check (@($preview.DeferredFields|Where-Object {$_.ItemId -ceq $service.ItemId -and $_.Field -ceq 'SecretRef'}).Count -eq 0) 'The LocalSystem service was deferred for an irrelevant empty optional SecretRef.'
        Check (@($preview.DeferredFields|Where-Object {$_.ItemId -ceq $passwordService.ItemId -and $_.Field -ceq 'SecretRef'}).Count -gt 0) 'The UserPassword service with no required SecretRef was not deferred.'
        $taskRow=@($preview.Items|Where-Object ItemId -CEQ $task.ItemId)[0]
        $taskEmptyArgumentForm=@(Get-WsmWizardPreparationForm ([ordered]@{WorkloadFieldReviews=@([pscustomobject]@{FieldPointer='Task/Actions/Action[0]/Arguments';Value=''})}) 'ScheduledTask')
        $taskOptionalReview=[pscustomobject]@{Adapter='ScheduledTask';ManualReviewRequired=$false;MissingTypedFields=@();FormFields=$taskEmptyArgumentForm};Check (@($taskEmptyArgumentForm|Where-Object {$_.key -ceq 'WorkloadFieldReviews/0/Value' -and -not $_.required -and $_.value -ceq ''}).Count -eq 1 -and @(Get-WsmWizardBulkPreparationEligibility $taskOptionalReview).Count -eq 0) 'A legitimate empty optional task argument was not retained as an optional typed value.'
        $optionalSecretReview=[pscustomobject]@{Adapter='Service';ManualReviewRequired=$false;MissingTypedFields=@();FormFields=@([pscustomobject]@{key='SecretRef';value='';required=$false;editable=$true;type='text';options=@();origin='NeedsHumanDecision';provenance=$null})};Check (@(Get-WsmWizardBulkPreparationEligibility $optionalSecretReview).Count -eq 0) 'An empty optional SecretRef was treated as a missing human decision.'
        $readonlyReview=[pscustomobject]@{Adapter='LocalGroup';ManualReviewRequired=$false;MissingTypedFields=@();FormFields=@([pscustomobject]@{key='Name';value='Existing group name';required=$true;editable=$false;type='text';options=@();origin='TrustedSourceInventory';provenance=$null})};Check (@(Get-WsmWizardBulkPreparationEligibility $readonlyReview).Count -eq 0) 'A valid required read-only source fact was incorrectly deferred.'
        $missingReadonlyReview=[pscustomobject]@{Adapter='LocalGroup';ManualReviewRequired=$false;MissingTypedFields=@();FormFields=@([pscustomobject]@{key='Name';value='';required=$true;editable=$false;type='text';options=@();origin='NeedsHumanDecision';provenance=$null})};Check (@(Get-WsmWizardBulkPreparationEligibility $missingReadonlyReview|Where-Object Reason -CEQ 'RequiredValueUnavailable').Count -eq 1) 'A missing required read-only source fact was not deferred.'
        Check (@($preview.DeferredFields|Where-Object {$_.ItemId -ceq $user.ItemId -and $_.Field -ceq 'SecretRef'}).Count -gt 0) 'The missing local-user SecretRef was not deferred.'
        Check (@($preview.DeferredFields|Where-Object {$_.ItemId -ceq $task.ItemId}).Count -gt 0) 'Opaque or human-required scheduled-task fields were not deferred.'
        Check (@($preview.Items|Where-Object {$_.ItemId -ceq $service.ItemId}|ForEach-Object {$_.FormFields}|Where-Object {$_.origin -in @('ConservativeDefault','TrustedSourceInventory')}).Count -gt 0) 'The preview did not expose source-default provenance for explicit review.'
        $operationId=[Guid]::NewGuid().ToString('D')
        Reject {Save-WsmWizardBulkPreparationReview -Workspace $work -PairId $catalog.PairId -PreviewId $preview.PreviewId -PreviewHash $preview.PreviewHash -Owner 'Bulk fixture owner' -Evidence 'Reviewed fixture evidence' -BusinessChecks @('Verify business files on target') -OperationId $operationId} 'Bulk source defaults were adopted without explicit confirmation.'
        Reject {Save-WsmWizardBulkPreparationReview -Workspace $work -PairId $catalog.PairId -PreviewId $preview.PreviewId -PreviewHash $preview.PreviewHash -Owner '' -Evidence 'Reviewed fixture evidence' -BusinessChecks @('Verify business files on target') -OperationId $operationId -ReviewedSourceDefaults} 'A blank shared owner was accepted.'
        Check ((Get-WsmCatalog $work $catalog.PairId).DecisionRevision -eq $catalog.DecisionRevision) 'A failed consent/owner check changed the authoritative catalog.'
        $before=Get-WsmCatalog $work $catalog.PairId
        $script:WsmBulkPreparationBeforeCoreSaveHook={throw 'Injected interruption before the first authoritative core Save.'}
        $prewriteError='';try{Save-WsmWizardBulkPreparationReview -Workspace $work -PairId $catalog.PairId -PreviewId $preview.PreviewId -PreviewHash $preview.PreviewHash -Owner 'Bulk fixture owner' -Evidence 'Reviewed fixture evidence for these exact source defaults.' -BusinessChecks @('Verify business files on target','Confirm required users can access the share') -OperationId $operationId -ReviewedSourceDefaults|Out-Null}catch{$prewriteError=$_.Exception.Message}
        $prewriteOperation=Read-WsmJson (Get-WsmWizardBulkPreparationOperationPath $work $catalog.PairId $operationId)
        Check ($prewriteError -match 'Injected interruption' -and (Get-WsmCatalog $work $catalog.PairId).DecisionRevision -eq $before.DecisionRevision -and $prewriteOperation.CurrentItemId -and $prewriteOperation.CurrentItemStatus -ceq 'Unknown') 'A pre-core failure did not retain an explicit unknown intent without falsely recording a write.'
        $script:WsmBulkPreparationAfterCoreSaveHook={throw 'Injected interruption after the first authoritative core Save and before the operation checkpoint.'}
        $interruptError='';try{Save-WsmWizardBulkPreparationReview -Workspace $work -PairId $catalog.PairId -PreviewId $preview.PreviewId -PreviewHash $preview.PreviewHash -Owner 'Bulk fixture owner' -Evidence 'Reviewed fixture evidence for these exact source defaults.' -BusinessChecks @('Verify business files on target','Confirm required users can access the share') -OperationId $operationId -ReviewedSourceDefaults|Out-Null}catch{$interruptError=$_.Exception.Message}
        Check ($interruptError -match 'Injected interruption') ('The after-core-save interruption hook did not fire: '+$interruptError)
        $interruptedCatalog=Get-WsmCatalog $work $catalog.PairId;$operationPath=Get-WsmWizardBulkPreparationOperationPath $work $catalog.PairId $operationId;$interruptedOperation=Read-WsmJson $operationPath
        Check ($interruptedCatalog.DecisionRevision -eq ($before.DecisionRevision+1) -and $interruptedOperation.CurrentItemId -and $interruptedOperation.CurrentItemStatus -ceq 'IntentUnknown') ('The injected interruption did not leave one authoritative write with an explicit unknown pending intent. revisions '+$before.DecisionRevision+'/'+$interruptedCatalog.DecisionRevision+' operation '+$interruptedOperation.CurrentItemId+'/'+$interruptedOperation.CurrentItemStatus)
        $saved=Save-WsmWizardBulkPreparationReview -Workspace $work -PairId $catalog.PairId -PreviewId $preview.PreviewId -PreviewHash $preview.PreviewHash -Owner 'Bulk fixture owner' -Evidence 'Reviewed fixture evidence for these exact source defaults.' -BusinessChecks @('Verify business files on target','Confirm required users can access the share') -OperationId $operationId -ReviewedSourceDefaults
        $after=Get-WsmCatalog $work $catalog.PairId
        Check ($saved.Status -ceq 'Succeeded' -and @($saved.SavedItemIds).Count -eq 2 -and $saved.SpecWrites -eq 1 -and -not $saved.BusinessAcceptance -and -not $saved.AuthoritativeApproval) 'The recovered bulk operation did not report one recovered plus one explicit save without claiming acceptance/approval.'
        Check ($after.DecisionRevision -eq ($before.DecisionRevision+2) -and -not $after.Approval) 'The batch did not use exactly one core CAS revision per candidate or changed approval state.'
        foreach($id in @($service.ItemId,$group.ItemId)){$row=@($after.Items|Where-Object ItemId -CEQ $id)[0];Check ([string]$row.MigrationSpec.Owner -ceq 'Bulk fixture owner' -and [string]$row.MigrationSpec.Evidence -ceq 'Reviewed fixture evidence for these exact source defaults.') ($row.MigrationSpec.Adapter+' did not receive the explicit common owner/evidence through the core save path.');$form=Get-WsmWizardPreparationReview $work $catalog.PairId $id;$previewItem=@($preview.Items|Where-Object ItemId -CEQ $id)[0];foreach($expectedField in @($previewItem.FormFields|Where-Object {$_.editable -and ($_.origin -in @('ConservativeDefault','TrustedSourceInventory') -or $_.key -ceq 'BusinessChecks')})){$actualField=@($form.FormFields|Where-Object key -CEQ $expectedField.key)[0];$expectedValue=$expectedField.value;if($expectedField.key -ceq 'BusinessChecks'){$expectedValue="Verify business files on target`nConfirm required users can access the share"};Check ((Get-WsmWizardBulkPreparationCanonicalValue $actualField.value ([string]$expectedField.type)) -ceq (Get-WsmWizardBulkPreparationCanonicalValue $expectedValue ([string]$expectedField.type))) ($row.MigrationSpec.Adapter+' recovery changed submitted answer '+$expectedField.key+'.')};$resultItem=@($saved.Items|Where-Object ItemId -CEQ $id)[0];Check (-not [string]::IsNullOrWhiteSpace([string]$resultItem.SpecPath)) 'The bulk result omitted the exact saved spec artifact path.';$artifact=@(Get-ChildItem -LiteralPath (Join-Path (Join-Path $work 'assistive') 'review-forms') -Filter ('spec-'+$catalog.PairId+'-'+$id+'-*.json')|Where-Object {$_.FullName -ceq [string]$resultItem.SpecPath -and (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -ceq [string]$resultItem.SpecHash});Check ($artifact.Count -eq 1) ($row.MigrationSpec.Adapter+' result SpecPath/SpecHash did not identify one exact readable artifact.');$artifactSpec=Read-WsmJson $artifact[0].FullName;Check ($artifactSpec.Owner -ceq 'Bulk fixture owner' -and $artifactSpec.Evidence -ceq 'Reviewed fixture evidence for these exact source defaults.') 'The saved spec bytes do not match the caller-reviewed common values.';Check ($resultItem.ReplayedWrite -eq ($id -ceq [string]$interruptedOperation.CurrentItemId)) 'The interrupted item was not marked recovered, or an ordinary core save was marked replayed.'}
        $replay=Save-WsmWizardBulkPreparationReview -Workspace $work -PairId $catalog.PairId -PreviewId $preview.PreviewId -PreviewHash $preview.PreviewHash -Owner 'Bulk fixture owner' -Evidence 'Reviewed fixture evidence for these exact source defaults.' -BusinessChecks @('Verify business files on target','Confirm required users can access the share') -OperationId $operationId -ReviewedSourceDefaults
        Check ($replay.Status -ceq 'Succeeded' -and $replay.SpecWrites -eq 1 -and (Get-WsmCatalog $work $catalog.PairId).DecisionRevision -eq $after.DecisionRevision) 'A same-operation replay rewrote specs or lost its durable outcome.'
        $refreshed=Get-WsmWizardBulkPreparationPreview -Workspace $work -PairId $catalog.PairId;Check (@($refreshed.SkippedExistingSpecItemIds|Where-Object {$_ -in @($service.ItemId,$group.ItemId)}).Count -eq 2) 'A future preview did not preserve and skip already-saved reviewed specifications.'
        Reject {Save-WsmWizardBulkPreparationReview -Workspace $work -PairId $catalog.PairId -PreviewId $preview.PreviewId -PreviewHash $preview.PreviewHash -Owner 'Different owner' -Evidence 'Different inputs' -BusinessChecks @('Verify business files on target') -OperationId $operationId -ReviewedSourceDefaults} 'An operation id was rebound to different explicit review inputs.'
        $stale=Get-WsmWizardBulkPreparationPreview -Workspace $work -PairId $catalog.PairId
        $staleCatalog=Get-WsmCatalog $work $catalog.PairId
        Set-WsmAssistiveSelections -Workspace $work -PairId $catalog.PairId -ExpectedRevision $staleCatalog.Assistive.Revision -ItemIds @($file.ItemId) -Selected $false -Reason 'Fixture selection changed after the preview.'|Out-Null
        $beforeStale=Get-WsmCatalog $work $catalog.PairId
        Reject {Save-WsmWizardBulkPreparationReview -Workspace $work -PairId $catalog.PairId -PreviewId $stale.PreviewId -PreviewHash $stale.PreviewHash -Owner 'Owner' -Evidence 'Evidence' -BusinessChecks @('Confirm result') -OperationId ([Guid]::NewGuid().ToString('D')) -ReviewedSourceDefaults} 'A stale selection-bound preview was applied.'
        Check ($beforeStale.DecisionRevision -eq (Get-WsmCatalog $work $catalog.PairId).DecisionRevision) 'A rejected stale preview changed the catalog.'
        Write-Output ('PASS: '+$script:bulkChecks+' bulk preview provenance, deferral, explicit inputs, CAS writes, and replay checks.')
    } $root (Join-Path $PSScriptRoot '../src/WizardPreparationBulk.ps1')
} finally {
    $absolute=[IO.Path]::GetFullPath($root);$prefix=[IO.Path]::GetFullPath($env:TEMP).TrimEnd('\')+'\'
    if(-not $absolute.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Test cleanup escaped the owned temporary root.'}
    Remove-Item -LiteralPath $absolute -Recurse -Force
}
